import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  uniform,
  texture,
  color,
  float,
  sin,
  fract,
  dot,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- root hierarchy ------------------------------------------------
  // group     -> external scenePosition applied by adapter, never touched here
  // inner     -> local entrance / idle motion (weighted-settle + breathing)
  // faceGroup -> billboarded toward camera each frame
  const group = new THREE.Group();
  group.name = 'pricing-card-1-sprite';

  const inner = new THREE.Group();
  group.add(inner);

  const faceGroup = new THREE.Group();
  inner.add(faceGroup);

  // ---- geometry sizing from atlas region -----------------------------
  const rect = { w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const cardHeight = 1.6; // scene units, respects 0.25 spacing rhythm
  const cardWidth = cardHeight * aspect;

  // ---- contact shadow (grounding, depth plane 1) ---------------------
  const shadowGeo = new THREE.PlaneGeometry(cardWidth * 1.35, cardHeight * 0.55);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sUv = uv();
  const sDist = sUv.sub(vec2(0.5, 0.5)).length();
  const sFalloff = float(1.0).sub(smoothstep(0.0, 0.5, sDist));
  shadowMat.colorNode = color(colors.surface);
  shadowMat.opacityNode = sFalloff.mul(0.5);
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -cardHeight * 0.62, -0.01);
  faceGroup.add(shadowMesh);

  // ---- engineered gradient card surface (depth plane 2, the subject) -
  const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight, 1, 1);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true, side: THREE.DoubleSide });

  const inkColor = color(colors.ink);
  const surfaceColor = color(colors.surface);

  const vUv = uv();
  const gradient = mix(surfaceColor, inkColor, vUv.y);

  // subtle procedural grain (no blur, engineered not pastel)
  const grainSeed = dot(vUv, vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainAmount = grain.sub(0.5).mul(0.035);

  cardMat.colorNode = gradient.add(vec3(grainAmount));
  cardMat.opacityNode = float(1.0);

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  faceGroup.add(cardMesh);

  // billboard toward camera every frame (full facing, driven by the mesh
  // that Three actually visits during render traversal)
  cardMesh.onBeforeRender = (renderer, scene, camera) => {
    faceGroup.quaternion.copy(camera.quaternion);
  };

  // ---- thin accent bar (<=10% of frame, the one accent hit) -----------
  const accentGeo = new THREE.PlaneGeometry(cardWidth * 0.86, cardHeight * 0.032);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  accentMat.colorNode = color(colors.accent);
  accentMat.opacityNode = float(0.9);
  const accentBar = new THREE.Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -cardHeight * 0.46, 0.002);
  faceGroup.add(accentBar);

  // ---- image asset (loaded async, composited over the gradient) ------
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (tex.colorSpace !== undefined) tex.colorSpace = THREE.SRGBColorSpace;
        loadedTexture = tex;
        const texNode = texture(tex, vUv);
        cardMat.colorNode = mix(gradient, texNode.rgb, texNode.a).add(vec3(grainAmount));
        cardMat.opacityNode = float(1.0);
        cardMat.needsUpdate = true;
      })
      .catch(() => {
        // keep gradient-only surface if the asset fails to resolve
      });
  }

  // ---- motion: weighted-settle entrance + slow idle breathing ---------
  const timelines = [];

  inner.scale.setScalar(0.96);
  faceGroup.position.y = -0.12;

  const settleTl = gsap.timeline();
  settleTl.to(inner.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.45,
    ease: 'power3.out',
  });
  settleTl.to(inner.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  settleTl.to(
    faceGroup.position,
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  timelines.push(settleTl);

  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.35 });
  breatheTl.to(inner.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(breatheTl);

  // ---- required contract ----------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    timelines.length = 0;

    cardMesh.onBeforeRender = () => {};

    shadowGeo.dispose();
    cardGeo.dispose();
    accentGeo.dispose();

    shadowMat.dispose();
    cardMat.dispose();
    accentMat.dispose();

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }
  };

  return group;
}
